/*
 * A376940  a(n) is the conductor of extension of Q generated by character
 *          values of the n-th alternating group A_n; the smallest m such that
 *          the extension is a subfield of the m-th cyclotomic field
 *          Q(zeta_m).
 * https://oeis.org/A376940
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = product of all odd primes p ≤ n, with the following
 *            skips: • Skip p = 2. • Skip p = n−2 if n−2 is an odd prime (this
 *            covers all n ≥ 25 and many small n). • Additionally skip: – p =
 *            3 for n = 6 or 7, – p = 5 for n = 10 or 11, – p = 7 for n = 14.
 *            This yields the conductor of Q(A_n)
 * Range:     u8 n <= 11, u16 n <= 16, u32 n <= 31, u64 n <= 58, u128 n <= 103,
 *            big any n
 * Helpers:   build_primes_upto, is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/build_primes_upto.h"   /* For build_primes_upto   */
#include "../utils/is_prime.h"           /* For is_prime           */

seq_t a(idx_t n) {
    static idx_t prime_limit = 0;
    static uint64_t *primes = NULL;
    static size_t primes_cnt = 0;

    /* Grow prime table if necessary (max n is small, so this is fast). */
    if (n > prime_limit) {
        idx_t new_limit = n;
        uint64_t *new_primes = NULL;
        size_t new_cnt = 0;
        build_primes_upto(new_limit, &new_primes, &new_cnt);
        if (primes) free(primes);
        primes   = new_primes;
        primes_cnt = new_cnt;
        prime_limit = new_limit;
    }

    seq_t prod = 1;
    for (size_t i = 0; i < primes_cnt; ++i) {
        uint64_t p = primes[i];
        if (p == 2) continue;           /* skip 2, only odd primes matter */

        bool skip = false;

        /* Skip p = n-2 if n-2 is an odd prime (covers all n ≥ 25). */
        if (n > 2 && ((n % 2ULL) == 1) && is_prime(n - 2) && p == n - 2) {
            skip = true;
        }

        /* Small‑n specific exclusions. */
        if ((n == 6 || n == 7) && p == 3)        skip = true;
        if ((n == 10 || n == 11) && p == 5)     skip = true;
        if (n == 14 && p == 7)                  skip = true;

        if (skip) continue;
        prod *= (seq_t)p;
    }

    return prod;
}
